-- (12/04/2023) Agregar y actualizar columnas de balance y balance antiguo de transacción bancaria
-- Crear tabla con balances de transacciones bancarias
DROP TABLE IF EXISTS `llx_bank_balance`;
CREATE TABLE llx_bank_balance (
  rowid INT(11) PRIMARY KEY NOT NULL AUTO_INCREMENT,
  fk_bank INT(11) NOT NULL,
  balance_antes DOUBLE(24,8),
  balance DOUBLE(24,8),
  FOREIGN KEY (fk_bank) REFERENCES llx_bank(rowid)
  ON DELETE CASCADE
);

-- Insertar balances para entradas antiguas
INSERT INTO llx_bank_balance (fk_bank, balance, balance_antes)
SELECT DISTINCT b.rowid,
  @balance := (
    SELECT SUM(amount)
    FROM llx_bank
    WHERE fk_account = b.fk_account
      AND (rowid <= b.rowid OR dateo < b.dateo)
  ),
  @balance - b.amount
FROM llx_bank b;

-- Trigger, insertar balances de nueva entrada en llx_bank
DELIMITER $$
CREATE TRIGGER update_bank_balance_insert
AFTER INSERT ON llx_bank
FOR EACH ROW
BEGIN
  DECLARE balance_before DOUBLE(24,8);
  DECLARE balance DOUBLE(24,8);

  SELECT COALESCE(SUM(amount), 0)
  INTO balance_before
  FROM llx_bank
  WHERE fk_account = NEW.fk_account
    AND (rowid < NEW.rowid OR dateo < NEW.dateo);

  SET balance = balance_before + NEW.amount;

  INSERT INTO llx_bank_balance (fk_bank, balance, balance_antes)
  VALUES (NEW.rowid, balance, balance_before);
END$$
DELIMITER ;

-- Trigger, actualizar balances de entrada en llx_bank
-- (para entrada actual y entradas con fecha futura)
DELIMITER $$
CREATE TRIGGER update_bank_balance_update
AFTER UPDATE ON llx_bank
FOR EACH ROW
BEGIN
  UPDATE llx_bank_balance bb
  JOIN llx_bank b ON bb.fk_bank = b.rowid
  SET bb.balance = (
    SELECT COALESCE(SUM(amount), 0)
    FROM llx_bank
    WHERE fk_account = b.fk_account
      AND (rowid <= b.rowid OR dateo < b.dateo)
  ),
  bb.balance_antes = (
    SELECT COALESCE(SUM(amount), 0)
    FROM llx_bank
    WHERE fk_account = b.fk_account
      AND (rowid < b.rowid OR dateo < b.dateo)
  )
  WHERE b.fk_account = NEW.fk_account
    AND b.dateo >= NEW.dateo;
END$$
DELIMITER ;
